private string CalcPercentNumber(int intCount, int intTotal)
{
    if (intTotal <= 0)
        return "&nbsp;";
    if (intCount <= 0)
        return "0%";
    return String.Format("{0}%", Math.Round((double)intCount * 100 / intTotal, 0));
}

